-- unit_latest (PV-26): one row per unit, kept current by ingest, so a fleet
-- read costs one row per unit instead of several passes over every check-in.
-- GENERATED by scripts/gen-0015.mjs from src/latest.js; don't edit by hand.
-- The views stay: they're the reference (and DataGrip's), and a test checks
-- that unit_latest agrees with them.
CREATE TABLE unit_latest (
  unit_key TEXT PRIMARY KEY,
  run_count INTEGER NOT NULL DEFAULT 0,
  monitor_posts INTEGER NOT NULL DEFAULT 0,
  first_seen,
  last_seen,
  last_launch,
  detail_at,
  detail_row,
  venue_id,
  vpu_name,
  model,
  pulse_version,
  channel,
  verdict_at,
  verdict_row,
  readiness_status,
  readiness_blockers,
  readiness_risks,
  kind_at,
  kind_row,
  last_kind,
  tel_at,
  tel_row,
  tel_venue_id,
  tel_vpu_name,
  tel_model,
  status,
  status_since,
  headline,
  blockers,
  internet_reachable,
  streaming_path,
  ports_failed,
  ip,
  subnet_mask,
  gateway,
  dns1,
  dns2,
  dhcp,
  mac,
  system_type,
  cameras_detected,
  cameras_expected,
  cameras_slow,
  services_down,
  scoreboard_source,
  scoreboard_ok,
  last_boot,
  unexpected_shutdowns_7d,
  pixellot_version,
  tel_pulse_version,
  telemetry,
  ev_at,
  ev_row,
  ev_id,
  ev_state,
  ev_kind,
  ev_on_air,
  ev_why,
  ev_path,
  ev_name,
  ev_warnings
);

-- One unit's history (Vitals' drawer) reads only that unit's rows.
CREATE INDEX IF NOT EXISTS checkins_unit ON checkins (COALESCE(venue_id, vpu_name, hostname, serial_number), received_at);
-- Finding transitions (Vitals' 7-day trends) read only the rows that carry them.
CREATE INDEX IF NOT EXISTS checkins_deltas ON checkins (COALESCE(sent_at, received_at))
  WHERE delta_opened IS NOT NULL OR delta_resolved IS NOT NULL;

