INSERT INTO unit_latest (unit_key, run_count, monitor_posts, first_seen, last_seen, last_launch, detail_at, detail_row, venue_id, vpu_name, model, pulse_version, channel, verdict_at, verdict_row, readiness_status, readiness_blockers, readiness_risks, kind_at, kind_row, last_kind, tel_at, tel_row, tel_venue_id, tel_vpu_name, tel_model, status, status_since, headline, blockers, internet_reachable, streaming_path, ports_failed, ip, subnet_mask, gateway, dns1, dns2, dhcp, mac, system_type, cameras_detected, cameras_expected, cameras_slow, services_down, scoreboard_source, scoreboard_ok, last_boot, unexpected_shutdowns_7d, pixellot_version, tel_pulse_version, telemetry, ev_at, ev_row, ev_id, ev_state, ev_kind, ev_on_air, ev_why, ev_path, ev_name, ev_warnings)
SELECT COALESCE(c.venue_id, c.vpu_name, c.hostname, c.serial_number) AS unit_key,
       CASE
    WHEN c.source = 'sheet-import' THEN COALESCE(CAST(json_extract(c.raw, '$.runCount') AS INTEGER), 1)
    WHEN c.telemetry IS NULL AND (c.reason IS NULL OR c.reason = 'startup') THEN 1
    ELSE 0 END AS run_count,
       CASE WHEN c.reason IN ('periodic', 'state-change', 'heartbeat') THEN 1 ELSE 0 END AS monitor_posts,
       CASE WHEN c.source = 'sheet-import' THEN json_extract(c.raw, '$.firstSeen') ELSE COALESCE(c.sent_at, c.received_at) END AS first_seen,
       CASE WHEN c.source = 'sheet-import' THEN COALESCE(c.sent_at, c.received_at) ELSE c.received_at END AS last_seen,
       CASE WHEN (CASE
    WHEN c.source = 'sheet-import' THEN COALESCE(CAST(json_extract(c.raw, '$.runCount') AS INTEGER), 1)
    WHEN c.telemetry IS NULL AND (c.reason IS NULL OR c.reason = 'startup') THEN 1
    ELSE 0 END) > 0 THEN COALESCE(c.sent_at, c.received_at) END AS last_launch,
       CASE WHEN c.pulse_version IS NOT NULL THEN COALESCE(c.sent_at, c.received_at) END AS detail_at,
       CASE WHEN c.pulse_version IS NOT NULL THEN c.id END AS detail_row,
       CASE WHEN c.pulse_version IS NOT NULL THEN c.venue_id END AS venue_id,
       CASE WHEN c.pulse_version IS NOT NULL THEN c.vpu_name END AS vpu_name,
       CASE WHEN c.pulse_version IS NOT NULL THEN c.model END AS model,
       CASE WHEN c.pulse_version IS NOT NULL THEN c.pulse_version END AS pulse_version,
       CASE WHEN c.pulse_version IS NOT NULL THEN c.channel END AS channel,
       CASE WHEN COALESCE(c.tel_status, c.readiness_status) IS NOT NULL AND c.reason IS NOT 'heartbeat' THEN COALESCE(c.sent_at, c.received_at) END AS verdict_at,
       CASE WHEN COALESCE(c.tel_status, c.readiness_status) IS NOT NULL AND c.reason IS NOT 'heartbeat' THEN c.id END AS verdict_row,
       CASE WHEN COALESCE(c.tel_status, c.readiness_status) IS NOT NULL AND c.reason IS NOT 'heartbeat' THEN COALESCE(c.tel_status, c.readiness_status) END AS readiness_status,
       CASE WHEN COALESCE(c.tel_status, c.readiness_status) IS NOT NULL AND c.reason IS NOT 'heartbeat' THEN c.readiness_blockers END AS readiness_blockers,
       CASE WHEN COALESCE(c.tel_status, c.readiness_status) IS NOT NULL AND c.reason IS NOT 'heartbeat' THEN c.readiness_risks END AS readiness_risks,
       CASE WHEN 1 THEN COALESCE(c.sent_at, c.received_at) END AS kind_at,
       CASE WHEN 1 THEN c.id END AS kind_row,
       CASE WHEN 1 THEN c.reason END AS last_kind,
       CASE WHEN c.telemetry IS NOT NULL THEN COALESCE(c.sent_at, c.received_at) END AS tel_at,
       CASE WHEN c.telemetry IS NOT NULL THEN c.id END AS tel_row,
       CASE WHEN c.telemetry IS NOT NULL THEN c.venue_id END AS tel_venue_id,
       CASE WHEN c.telemetry IS NOT NULL THEN c.vpu_name END AS tel_vpu_name,
