       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_headline END AS headline,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_blockers END AS blockers,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_internet_reachable END AS internet_reachable,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_streaming_path END AS streaming_path,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_ports_failed END AS ports_failed,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_ip END AS ip,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_subnet_mask END AS subnet_mask,
