       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_dhcp END AS dhcp,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_mac END AS mac,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_system_type END AS system_type,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_cameras_detected END AS cameras_detected,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_cameras_expected END AS cameras_expected,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_cameras_slow END AS cameras_slow,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_services_down END AS services_down,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_scoreboard_source END AS scoreboard_source,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_scoreboard_ok END AS scoreboard_ok,
       CASE WHEN c.telemetry IS NOT NULL THEN c.tel_last_boot END AS last_boot,
