       CASE WHEN c.event_id IS NOT NULL THEN COALESCE(c.sent_at, c.received_at) END AS ev_at,
       CASE WHEN c.event_id IS NOT NULL THEN c.id END AS ev_row,
       CASE WHEN c.event_id IS NOT NULL THEN c.event_id END AS ev_id,
