       CASE WHEN c.event_id IS NOT NULL THEN c.event_reason END AS ev_why,
       CASE WHEN c.event_id IS NOT NULL THEN json_extract(c.event, '$.path') END AS ev_path,
       CASE WHEN c.event_id IS NOT NULL THEN json_extract(c.event, '$.eventName') END AS ev_name,
       CASE WHEN c.event_id IS NOT NULL THEN json_extract(c.event, '$.warnings') END AS ev_warnings
