        OR (excluded.ev_at = unit_latest.ev_at AND excluded.ev_row > unit_latest.ev_row))) THEN excluded.ev_on_air ELSE unit_latest.ev_on_air END,
  ev_why = CASE WHEN (excluded.ev_at IS NOT NULL AND (unit_latest.ev_at IS NULL OR excluded.ev_at > unit_latest.ev_at
        OR (excluded.ev_at = unit_latest.ev_at AND excluded.ev_row > unit_latest.ev_row))) THEN excluded.ev_why ELSE unit_latest.ev_why END,
  ev_path = CASE WHEN (excluded.ev_at IS NOT NULL AND (unit_latest.ev_at IS NULL OR excluded.ev_at > unit_latest.ev_at
        OR (excluded.ev_at = unit_latest.ev_at AND excluded.ev_row > unit_latest.ev_row))) THEN excluded.ev_path ELSE unit_latest.ev_path END,
  ev_name = CASE WHEN (excluded.ev_at IS NOT NULL AND (unit_latest.ev_at IS NULL OR excluded.ev_at > unit_latest.ev_at
        OR (excluded.ev_at = unit_latest.ev_at AND excluded.ev_row > unit_latest.ev_row))) THEN excluded.ev_name ELSE unit_latest.ev_name END,
  ev_warnings = CASE WHEN (excluded.ev_at IS NOT NULL AND (unit_latest.ev_at IS NULL OR excluded.ev_at > unit_latest.ev_at
